inline nlohmann::json client_setup_contract(const nlohmann::json& notifications,const std::string& mode){
    using nlohmann::json;
    json connection=json::object();for(const auto* key:{"transport","host","port","tls","authentication","protocol_version"})if(notifications.contains(key))connection[key]=notifications[key];
    const json hello={{"type","hello"},{"device_id","watch-1"},{"token","<device-token>"}};
    auto resume=hello;resume["after_sequence"]=42;
    return {
        {"overview",{{"current_authentication",mode},{"scope","These instructions cover both open and token-enabled instances, regardless of this server's current mode. Endpoint permissions describe token-mode requirements; open mode does not enforce credentials."},{"bootstrap","Obtain the HTTPS base URL, device ID and device token from an administrator before connecting to a token-enabled server. GET /api itself requires discovery.read; it is not an unauthenticated bootstrap endpoint."}}},
        {"provisioning",{{"device_token","An administrator issues a separate device credential through /admin/credentials/explorer or POST /admin/credentials. Store the token securely; plaintext is shown only at issuance. Issuing a token does not create a device registry entry. Device tokens have no built-in expiry; rotate by issuing a replacement, updating the client, then revoking the old credential."},{"permissions","Request discovery.read for /api and /api/docs, notifications.read for TCP, and the read/write permissions for the resource families the device uses. Example: discovery.read + notifications.read + events.read allows discovery and calendar notifications/state. An administrator role alone does not grant all permissions."},{"registration","If device metadata is needed, POST /devices/{id} with local_ip (and optional external_ip), using devices.write. TCP does not require an existing registry record."},{"identity","Use a device ID matching the token subject. Device IDs are 1–64 ASCII letters, digits, _ or -. devices.delegate permits acting for other devices; ordinary clients should use their own identity."}}},
        {"rest",{{"header",{{"Authorization","Bearer <device-token>"}}},{"request_example","GET /api HTTP/1.1\r\nHost: <spark-host>\r\nAuthorization: Bearer <device-token>\r\n\r\n"},{"usage","Send the Authorization header on every protected REST request, including file downloads. The token is used directly; device clients do not log in through /auth/login or exchange it for a browser session. Never put the account token in a URL. Public file lease links are a separate, file-specific exception."},{"inspect_permissions",{{"method","POST"},{"path","/auth/verify"},{"headers",{{"Authorization","Bearer <device-token>"},{"Content-Type","application/json"}}},{"body",{{"device_id","watch-1"}}},{"result","Returns authenticated, device_id and this credential's current permissions. Requires a valid device token but no extra permission. Administrator tokens are rejected. Open mode returns authenticated=false and auth_mode=open."}}},{"errors",{{"401","Missing, invalid or revoked credential. Replace/reprovision credentials rather than retrying indefinitely."},{"403","Credential accepted but permission or device identity is insufficient; inspect the error code and granted permissions."}}}}},
        {"tcp",{{"connection",connection},{"transport","Use notifications.transport, host and port from this instance's contract. If host is omitted, use the REST hostname with the advertised TCP port. tcp+tls requires TLS with trusted certificate-chain and hostname verification, and SNI for that hostname. It is raw TCP carrying JSON, not HTTP or WebSocket. Browser cookies do not authenticate it. Never send tokens over an untrusted plaintext connection."},{"open_hello",{{"type","hello"},{"device_id","watch-1"}}},{"authenticated_hello",hello},{"authenticated_resume_hello",resume},{"wire_example","{\"type\":\"hello\",\"device_id\":\"watch-1\",\"token\":\"<device-token>\"}\n"},{"token_format","hello.token is the raw token string (for example the issued spark1_… value), without the Bearer prefix. Use the same device credential as REST. Supply token again on every new connection, including reconnects."},{"framing","UTF-8 JSON, one object followed by a newline per frame. Do not pretty-print frames. Buffer until newline: one socket read may contain partial or multiple frames. Send hello within 10 seconds, at most 4096 bytes. Wait for welcome before treating the connection as ready."},{"permissions","TCP requires notifications.read and permission to act as hello.device_id. Resource notifications are further filtered by read grants (for example events.read or files.read), pulse subscriptions and command eligibility. A successful welcome does not imply access to every event family."},{"recovery","Reply to each ping with a newline-terminated {\"type\":\"pong\"}. Reconnect with backoff and jitter, capped at 30 seconds. Use after_sequence only for the last durably processed sequence; never event_id. Omit it if no saved state exists. Follow welcome.resync_required and welcome.resources, plus checkpoint and catchup_complete as described in the full notification contract. Treat reminders replayed from history as state-refresh hints."},{"errors",{{"example",{{"type","error"},{"error","unauthorized"}}},{"unauthorized","Missing, invalid or revoked token; connection closes. Acquire valid credentials before reconnecting."},{"forbidden","Missing notifications.read or device identity mismatch; connection closes."},{"invalid_hello","Malformed hello, unsupported fields, wrong types or invalid device_id/cursor. Do not send an HTTP Authorization header on this socket."},{"revocation","Credential validity is checked during the connection. Revocation or credential changes can close it; reconnect with the updated token. Already-started HTTP transfers may finish."}}}}},
        {"browser_sessions",{{"google_login",{{"availability","GET /auth/google/options returns enabled. Optional Google owner login is browser-only; it does not replace device tokens for REST/TCP."},{"start","POST /auth/google/start with exact Origin, X-SPARK-Login: 1 and JSON {remember_device:false}; navigate to returned authorization_url. The server validates the callback and creates the same SPARK browser session."},{"enrolment","Administrator browser session with admin.credentials: open /admin/google/explorer. Enrolment binds one Google subject, with the initiating administrator permissions. Token login remains the recovery method."}}},{"audience","The human interfaces use administrator browser sessions. Device tokens cannot log in here and browser cookies cannot replace hello.token."},{"login",{{"method","POST"},{"path","/auth/login"},{"headers",{{"Content-Type","application/json"},{"Origin","<configured HTTPS browser_origin>"},{"X-SPARK-Login","1"}}},{"body",{{"token","<administrator-token>"},{"remember_device",false}}}}},{"follow_up","Retain the Secure HttpOnly SameSite=Strict cookie. GET /auth/session returns identity, permissions and csrf_token. Send exact Origin and X-SPARK-CSRF: <csrf_token> on mutations, including POST /auth/logout. Use same-origin requests over the configured HTTPS origin. Browser sessions are not a cross-origin device authentication mechanism."},{"lifetime","Maximum 12 hours; default 30-minute idle timeout. remember_device=true removes only the idle timeout. A process restart clears sessions."}}}
    };
}
